insert into public.products (id, name, house, type, size, price, image, tagline, story, notes, ingredients, feel, featured, world, sound, nozzle, sort) values
('noir-confidence', 'Noir Confidence', 'Inspired by Gucci Guilty', 'perfume', '60 ml · Eau de Parfum', 600, 'assets/img/hd/noir-confidence.webp', 'A scent of confidence.', 'Bold, magnetic and hard to forget. Mandarin and pink pepper open bright and sharp, lavender and orange blossom bring a clean, polished heart, and patchouli, cedar and amber stay close to the skin long into the night. For the days you walk in as if you own the room.', '{"top":["Mandarin","Pink Pepper","Bergamot"],"heart":["Lavender","Orange Blossom","Geranium"],"base":["Patchouli","Cedarwood","Amber"]}'::jsonb, array['citrus', 'bergamot', 'orangeblossom', 'cedar', 'amber']::text[], array['Bold', 'Magnetic', 'Unforgettable']::text[], false, null, 'rain', '[0.5,0.02]'::jsonb, 82),
('reverie', 'Reverie', 'Inspired by Louis Vuitton Imagination', 'perfume', '60 ml · Eau de Parfum', 600, 'assets/img/hd/reverie.webp', 'Luxury in every breath.', 'A fragrance that doesn’t just make you smell good; it makes you feel something. Bright citrus and bergamot with a whisper of fresh spice, a heart of lavender and soft amber, and a clean trail of musk, cedar and ambergris. Light enough for every day, memorable enough to be asked about.', '{"top":["Citrus","Bergamot","Fresh Spices"],"heart":["Lavender","Amber","Woody Accord"],"base":["Musk","Cedarwood","Ambergris"]}'::jsonb, array['citrus', 'bergamot', 'cardamom', 'amber', 'cedar', 'musk']::text[], array['Elegant', 'Fresh', 'Luminous']::text[], false, null, 'sea', '[0.5,0.02]'::jsonb, 84)
